-- seeder.sql · TAMACHIHUA-ERP
--
-- Datos de prueba para una ferretería y agroservicio real.
-- Cobertura: junio de 2026 a noviembre de 2026 (hasta el 23/11/2026).
--
-- Ejecutar DESPUÉS de las migraciones Flyway:
--   psql "$DB_URL" -U "$DB_USERNAME" -f Base_datos/seeder.sql
--
-- El script limpia las tablas de negocio (no toca flyway_schema_history)
-- y vuelve a cargar roles, usuarios, catálogos, productos, precios,
-- proveedores, lotes, clientes, ventas, facturación, pagos y notas de
-- crédito. Las imágenes de las presentaciones quedan en NULL para que se
-- asignen por URL desde la aplicación.
--
-- Usuario administrador:
--   username: mgomez
--   password: marvin_0305
--
-- Otros usuarios de prueba:
--   bodega   / bodega_0305    (WAREHOUSE)
--   compras  / compras_0305   (PURCHASING)
--   ventas1  / ventas_0305    (SELLER)
--   ventas2  / ventas2_0305   (SELLER)
-- =====================================================================

SET client_encoding = 'UTF8';
SET TIME ZONE 'America/El_Salvador';

BEGIN;

TRUNCATE TABLE
  invoice_payments,
  invoice_details,
  invoices,
  sale_lot_allocations,
  sale_details,
  sales,
  document_sequences,
  product_lots,
  product_prices,
  product_presentations,
  products,
  product_models,
  presentations,
  measure_units,
  product_brands,
  product_types,
  product_categories,
  customers,
  suppliers,
  users,
  roles
RESTART IDENTITY CASCADE;


























-- ---------------------------------------------------------------------
-- Sincronizar secuencias con los identificadores cargados
-- ---------------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('roles', 'id'), COALESCE((SELECT MAX(id) FROM roles), 1), true);
SELECT setval(pg_get_serial_sequence('users', 'id'), COALESCE((SELECT MAX(id) FROM users), 1), true);
SELECT setval(pg_get_serial_sequence('product_categories', 'id'), COALESCE((SELECT MAX(id) FROM product_categories), 1), true);
SELECT setval(pg_get_serial_sequence('product_types', 'id'), COALESCE((SELECT MAX(id) FROM product_types), 1), true);
SELECT setval(pg_get_serial_sequence('product_brands', 'id'), COALESCE((SELECT MAX(id) FROM product_brands), 1), true);
SELECT setval(pg_get_serial_sequence('product_models', 'id'), COALESCE((SELECT MAX(id) FROM product_models), 1), true);
SELECT setval(pg_get_serial_sequence('measure_units', 'id'), COALESCE((SELECT MAX(id) FROM measure_units), 1), true);
SELECT setval(pg_get_serial_sequence('presentations', 'id'), COALESCE((SELECT MAX(id) FROM presentations), 1), true);
SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX(id) FROM products), 1), true);
SELECT setval(pg_get_serial_sequence('product_presentations', 'id'), COALESCE((SELECT MAX(id) FROM product_presentations), 1), true);
SELECT setval(pg_get_serial_sequence('product_prices', 'id'), COALESCE((SELECT MAX(id) FROM product_prices), 1), true);
SELECT setval(pg_get_serial_sequence('suppliers', 'id'), COALESCE((SELECT MAX(id) FROM suppliers), 1), true);
SELECT setval(pg_get_serial_sequence('product_lots', 'id'), COALESCE((SELECT MAX(id) FROM product_lots), 1), true);
SELECT setval(pg_get_serial_sequence('customers', 'id'), COALESCE((SELECT MAX(id) FROM customers), 1), true);
SELECT setval(pg_get_serial_sequence('document_sequences', 'id'), COALESCE((SELECT MAX(id) FROM document_sequences), 1), true);
SELECT setval(pg_get_serial_sequence('sales', 'id'), COALESCE((SELECT MAX(id) FROM sales), 1), true);
SELECT setval(pg_get_serial_sequence('sale_details', 'id'), COALESCE((SELECT MAX(id) FROM sale_details), 1), true);
SELECT setval(pg_get_serial_sequence('sale_lot_allocations', 'id'), COALESCE((SELECT MAX(id) FROM sale_lot_allocations), 1), true);
SELECT setval(pg_get_serial_sequence('invoices', 'id'), COALESCE((SELECT MAX(id) FROM invoices), 1), true);
SELECT setval(pg_get_serial_sequence('invoice_details', 'id'), COALESCE((SELECT MAX(id) FROM invoice_details), 1), true);
SELECT setval(pg_get_serial_sequence('invoice_payments', 'id'), COALESCE((SELECT MAX(id) FROM invoice_payments), 1), true);

COMMIT;

-- =====================================================================
-- Resumen de datos cargados
-- =====================================================================
SELECT 'roles' AS tabla, COUNT(*) AS filas FROM roles
UNION ALL SELECT 'users', COUNT(*) FROM users
UNION ALL SELECT 'product_categories', COUNT(*) FROM product_categories
UNION ALL SELECT 'product_types', COUNT(*) FROM product_types
UNION ALL SELECT 'product_brands', COUNT(*) FROM product_brands
UNION ALL SELECT 'product_models', COUNT(*) FROM product_models
UNION ALL SELECT 'measure_units', COUNT(*) FROM measure_units
UNION ALL SELECT 'presentations', COUNT(*) FROM presentations
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'product_presentations', COUNT(*) FROM product_presentations
UNION ALL SELECT 'product_prices', COUNT(*) FROM product_prices
UNION ALL SELECT 'suppliers', COUNT(*) FROM suppliers
UNION ALL SELECT 'product_lots', COUNT(*) FROM product_lots
UNION ALL SELECT 'customers', COUNT(*) FROM customers
UNION ALL SELECT 'sales', COUNT(*) FROM sales
UNION ALL SELECT 'sale_details', COUNT(*) FROM sale_details
UNION ALL SELECT 'sale_lot_allocations', COUNT(*) FROM sale_lot_allocations
UNION ALL SELECT 'invoices', COUNT(*) FROM invoices
UNION ALL SELECT 'invoice_details', COUNT(*) FROM invoice_details
UNION ALL SELECT 'invoice_payments', COUNT(*) FROM invoice_payments
ORDER BY tabla;
